import{_ as t,o as s,c as i,a4 as r}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"ADR-0075 — Socle figé par empreinte, correctifs système appliqués à la construction","description":"Extrait de docs/adr/0075-socle-fige-et-correctifs-a-la-construction.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0075 — Socle figé par empreinte, correctifs système appliqués à la construction","description":"Extrait de docs/adr/0075-socle-fige-et-correctifs-a-la-construction.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0075-socle-fige-et-correctifs-a-la-construction.md","filePath":"developpeurs/adr/0075-socle-fige-et-correctifs-a-la-construction.md"}'),a={name:"developpeurs/adr/0075-socle-fige-et-correctifs-a-la-construction.md"};function n(o,e,c,l,u,d){return s(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-0075--socle-figé-par-empreinte-correctifs-système-appliqués-à-la-construction" tabindex="-1">ADR-0075 — Socle figé par empreinte, correctifs système appliqués à la construction <a class="header-anchor" href="#adr-0075--socle-figé-par-empreinte-correctifs-système-appliqués-à-la-construction" aria-label="Permalink to &quot;ADR-0075 — Socle figé par empreinte, correctifs système appliqués à la construction {#adr-0075--socle-figé-par-empreinte-correctifs-système-appliqués-à-la-construction}&quot;">​</a></h1><p><strong>Date :</strong> 4 novembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> audit complet du 21 octobre 2026, constats EXP-20 (« Le choix d&#39;<code>apk upgrade</code> n&#39;est consigné dans aucune ADR ») et EXP-21 (« Effets de bord d&#39;<code>apk upgrade</code> »), et SUIVI-17 ; commit <code>e034881</code> (18/10/2026, issue #35) ; lot 2 de l&#39;audit, accepté par le Product Owner le 21/10/2026 <strong>Amende :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0006-image-base-node-admin-alpine">ADR-0006</a> (section « Mise à jour — pinning par digest », argument de reproductibilité) et <a href="/teuthis-cms-distribution/developpeurs/adr/0007-image-base-python-api-alpine">ADR-0007</a> (conséquences, même argument) <strong>Complétée par :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0076-ce-qui-est-verifie-est-ce-qui-est-signe">ADR-0076</a> (l&#39;image analysée et essayée est celle qu&#39;on signe)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Les ADR-0006 et 0007 épinglent les images de base <code>node:22-alpine</code> et <code>python:3.12-alpine</code> par empreinte, « pour la reproductibilité des builds (build identique bit-à-bit d&#39;un run CI à l&#39;autre) ». Les Dockerfiles le répètent en commentaire.</p><p>Le 18/10/2026, une vulnérabilité haute de <code>zlib</code> (CVE-2026-85091) restait dans les images publiées alors que le correctif Alpine était sorti : Docker Hub republie les étiquettes avec retard, et une base figée par empreinte fige aussi ses paquets système jusqu&#39;au prochain rafraîchissement de l&#39;empreinte par Renovate. Le commit <code>e034881</code> a donc ajouté <code>RUN apk upgrade --no-cache</code> à l&#39;étape finale des trois Dockerfiles. Ce choix n&#39;a été consigné dans aucune ADR, et il rend faux l&#39;argument « identique bit à bit » : deux constructions du même commit, à deux dates, n&#39;installent pas forcément les mêmes paquets Alpine.</p><p>Effets de bord relevés par l&#39;audit (EXP-21) : la construction exige le réseau des miroirs Alpine ; un build local réutilise la couche <code>apk upgrade</code> en cache et fige les correctifs du jour où elle a été faite ; le chemin arm64 n&#39;est exercé qu&#39;à la publication et à la répétition à blanc ; les images 0.11.1 déjà publiées gardent la CVE.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>1. Le socle reste figé par empreinte.</strong> Les <code>FROM</code> restent épinglés par empreinte, rafraîchis par Renovate (PR relue, pas de fusion automatique). L&#39;empreinte du <code>FROM</code> dit d&#39;où l&#39;on part, pas ce que l&#39;on livre.</p><p><strong>2. Les correctifs système Alpine s&#39;appliquent à la construction.</strong> <code>RUN apk upgrade --no-cache</code> reste dans l&#39;étape finale de chaque Dockerfile (<code>production</code>), et dans elle seule : les étapes de construction n&#39;atteignent pas l&#39;image livrée. On ne court pas après une republication de Docker Hub pour livrer un correctif publié.</p><p><strong>3. On renonce à l&#39;argument « identique bit à bit ».</strong> Ce qui fait foi n&#39;est pas le Dockerfile, c&#39;est l&#39;image publiée : figée par son empreinte, signée par cosign, décrite par son SBOM et par son attestation de provenance, toutes deux poussées avec elle. Les paquets système réellement livrés se lisent dans le SBOM de l&#39;empreinte, pas dans le Dockerfile. Les dépendances applicatives, elles, restent reproductibles : fichiers verrouillés et hachés (<code>requirements*.txt</code>, <code>package-lock.json</code>), backend de construction compris.</p><p><strong>4. Conséquence sur la chaîne de publication.</strong> Puisque deux constructions diffèrent, l&#39;analyse de vulnérabilités et l&#39;essai de démarrage doivent porter sur l&#39;empreinte publiée, pas sur une construction voisine : c&#39;est l&#39;objet de l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0076-ce-qui-est-verifie-est-ce-qui-est-signe">ADR-0076</a>.</p><p><strong>5. Analyses locales sans cache.</strong> <code>.github/scripts/analyser-images.sh</code> construit avec <code>--no-cache</code> : une analyse locale ne doit pas porter sur une couche <code>apk upgrade</code> ancienne.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Revenir au seul rafraîchissement de l&#39;empreinte par Renovate</strong></td><td>Le correctif n&#39;arrive qu&#39;après la republication de Docker Hub, puis la PR Renovate : le cas zlib du 18/10 a montré que cela laisse une vulnérabilité corrigée dans les images publiées.</td></tr><tr><td><strong>Figer chaque paquet Alpine (<code>apk add paquet=version</code>)</strong></td><td>Reproductible, mais il faut tenir la liste à jour à la main pour chaque correctif, et Alpine ne garde pas les anciennes révisions dans ses miroirs : la construction casse à la révision suivante.</td></tr><tr><td><strong>Passer à une base distroless ou construite depuis un instantané daté</strong> (miroir figé, comme <code>snapshot.debian.org</code>)</td><td>Reproductible et à jour, mais Alpine n&#39;offre pas d&#39;instantané public de ses miroirs, et changer de base est un chantier sans rapport avec le défaut constaté. À reconsidérer si la reproductibilité bit à bit devient une exigence.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Un correctif de sécurité Alpine publié entre dans la version suivante sans attendre Docker Hub.</li><li>L&#39;argument écrit dans les ADR et les Dockerfiles correspond à ce que fait le code.</li></ul><p><strong>Négatives</strong></p><ul><li>La construction exige le réseau des miroirs Alpine : sans lui, elle échoue (et ne livre rien de périmé en silence).</li><li>Deux constructions du même commit peuvent différer : on ne peut plus vérifier une image publiée en la reconstruisant. On la vérifie par sa signature, son SBOM et sa provenance.</li><li>Les images 0.11.1 publiées gardent la CVE de zlib : seule une nouvelle version la retire des instances.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Commentaires des trois Dockerfiles corrigés : plus d&#39;argument « reproductible », renvoi à cette ADR. — <code>apps/api/Dockerfile</code>, <code>apps/admin/Dockerfile</code>, <code>apps/front/Dockerfile</code>.</li><li>[x] Analyses locales sans cache. — <code>.github/scripts/analyser-images.sh</code> (<code>--no-cache</code>).</li><li>[x] <strong>Répétition à blanc de <code>publication-images.yml</code> avant la version 0.11.2</strong> (EXP-21 : le chemin arm64 avec <code>apk upgrade</code> n&#39;avait jamais tourné). — Preuves : run 42051208910 du 05/11/2026 (sur <code>2be2cdb</code>), rouge sur une seule cause, pypdf 6.19.0 dans l&#39;image API (dix vulnérabilités HIGH relevées par Trivy), corrigée par <code>8659c4f</code> (pypdf 6.21.4) ; puis run 42056132162 (sur <code>8659c4f</code>), vert : trois images construites en amd64 et en arm64, vérifiées et analysées en amd64 (Alpine 3.24.2 sans vulnérabilité HIGH ni CRITICAL corrigeable : zlib est bien corrigé), archive et installateur préparés.</li><li>[ ] <strong>Analyser les images 0.11.3 publiées</strong> (la 0.11.2 n&#39;a pas été distribuée, voir l&#39;ADR-0076) (Trivy ou Docker Scout sur l&#39;empreinte de GHCR) et noter ici que la CVE-2026-85091 a disparu de ce qui est réellement déployé (SUIVI-17).</li></ul>',21)])])}const g=t(a,[["render",n]]);export{m as __pageData,g as default};
